-- seg_ch_1024
CREATE TABLE uav_search.seg_ch_1024\n(\n    `segment_id` String,\n    `dataset_id` LowCardinality(String),\n    `video_id` String,\n    `t_start` Float32,\n    `t_end` Float32,\n    `altitude_m` Float32,\n    `velocity_mps` Float32,\n    `gimbal_pitch` Float32,\n    `person_count` UInt16,\n    `vehicle_count` UInt16,\n    `is_night` UInt8,\n    `embedding` Array(Float32) CODEC(NONE),\n    INDEX idx_vec embedding TYPE vector_similarity(\'hnsw\', \'cosineDistance\', 1024) GRANULARITY 100000000,\n    INDEX idx_alt altitude_m TYPE minmax GRANULARITY 4,\n    INDEX idx_vel velocity_mps TYPE minmax GRANULARITY 4,\n    INDEX idx_per person_count TYPE minmax GRANULARITY 4\n)\nENGINE = MergeTree\nORDER BY (dataset_id, video_id, t_start)\nSETTINGS index_granularity = 8192;

