-- telemetry_raw
CREATE TABLE uav_search.telemetry_raw\n(\n    `dataset_id` LowCardinality(String),\n    `video_id` String,\n    `frame_index` UInt32,\n    `timestamp` DateTime64(6),\n    `latitude` Nullable(Float64),\n    `longitude` Nullable(Float64),\n    `altitude_m` Nullable(Float32),\n    `velocity_mps` Nullable(Float32),\n    `gimbal_pitch` Nullable(Float32),\n    `compass_heading` Nullable(Float32),\n    `gimbal_heading` Nullable(Float32),\n    `extra` Map(String, Float64)\n)\nENGINE = MergeTree\nORDER BY (dataset_id, video_id, frame_index)\nSETTINGS index_granularity = 8192;
